//! The JavaScript assets generated by `Linux/scripts/build-shared-js.mjs`.

use std::collections::HashMap;
use std::io;
use std::path::PathBuf;
use std::sync::{Arc, Mutex};

use crate::json::{Object, parse_object};

/// The kernel, the compiler bundle, the host files and the runtime contract.
/// Files are read once and kept.
pub struct SharedScripts {
    directory: PathBuf,
    cache: Mutex<HashMap<String, Arc<str>>>,
    host_files: Vec<String>,
    contract: Object,
    error_categories: Object,
}

impl SharedScripts {
    /// `directory` is the folder with kernel.js and the other assets.
    pub fn new(directory: impl Into<PathBuf>) -> io::Result<Self> {
        let directory = directory.into();
        if !directory.join("kernel.js").is_file() {
            return Err(io::Error::new(
                io::ErrorKind::NotFound,
                format!("ScriptWidget runtime assets are missing in {}. In a checkout, run node Linux/scripts/build-shared-js.mjs.", directory.display()),
            ));
        }
        // host.js defines the registry the API files add themselves to.
        let mut api_files: Vec<String> = std::fs::read_dir(&directory)?
            .filter_map(|entry| entry.ok()?.file_name().into_string().ok())
            .filter(|name| name.starts_with("apis-") && name.ends_with(".js"))
            .collect();
        api_files.sort_unstable();
        let mut host_files = vec!["host.js".to_owned()];
        host_files.append(&mut api_files);

        let invalid = |message: String| io::Error::new(io::ErrorKind::InvalidData, format!("contract.json: {message}"));
        let contract_file = parse_object(&std::fs::read_to_string(directory.join("contract.json"))?).map_err(invalid)?;
        let member = |name: &str| contract_file.get(name).and_then(|value| value.as_object()).cloned().ok_or_else(|| invalid(format!("{name} is missing")));
        Ok(Self { contract: member("contract")?, error_categories: member("errorCategories")?, directory, cache: Mutex::new(HashMap::new()), host_files })
    }

    /// The assets of this installation: see [`crate::resources`] for where they are looked for.
    pub fn default_directory() -> io::Result<PathBuf> {
        Ok(crate::resources::Resources::locate()?.runtime)
    }

    /// Text of one asset. `name` is a file name chosen by the host, never by a package.
    pub fn text(&self, name: &str) -> io::Result<Arc<str>> {
        let mut cache = self.cache.lock().unwrap_or_else(|poisoned| poisoned.into_inner());
        if let Some(text) = cache.get(name) {
            return Ok(text.clone());
        }
        let text: Arc<str> = std::fs::read_to_string(self.directory.join(name))
            .map_err(|error| io::Error::new(error.kind(), format!("{name}: {error}")))?
            .into();
        cache.insert(name.to_owned(), text.clone());
        Ok(text)
    }

    /// Host files evaluated before the kernel, in order.
    pub fn host_files(&self) -> &[String] {
        &self.host_files
    }

    pub fn contract(&self) -> &Object {
        &self.contract
    }

    pub fn error_categories(&self) -> &Object {
        &self.error_categories
    }

    /// The scripts a package may load with `$import`-style support calls; any other name is refused.
    pub fn support_script(&self, name: &str) -> Option<Arc<str>> {
        match name {
            "util.js" | "moment.min.js" => self.text(name).ok(),
            _ => None,
        }
    }
}
